import{_ as t,o,c as r,ag as l}from"./chunks/framework.CAXxHpAX.js";const d=JSON.parse('{"title":"对境不住","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-对境不住.md","filePath":"10-核心模型/model-对境不住.md","lastUpdated":1778033203000}'),e={name:"10-核心模型/model-对境不住.md"};function n(i,a,s,h,u,q){return o(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="对境不住" tabindex="-1">对境不住 <a class="header-anchor" href="#对境不住" aria-label="Permalink to &quot;对境不住&quot;">​</a></h1><blockquote><p>了空居士智慧体系第一心法。 不被现象所迷惑，保持最清净的心去看待一切。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>对境不住</strong> 是了空居士教导中最核心的心法。它不是排斥念头、逃避现象，而是<strong>客观地面对一切现象而不被情绪扰动</strong>，如同明镜照物，物来不拒，物去不留。</p><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="_1-无所住生心" tabindex="-1">1. 无所住生心 <a class="header-anchor" href="#_1-无所住生心" aria-label="Permalink to &quot;1. 无所住生心&quot;">​</a></h3><p><strong>原文</strong>：《金刚经》的核心就是&quot;应无所住而生其心&quot;。</p><p><strong>解读</strong>：&quot;无所住&quot;是不执着于任何事物，&quot;生心&quot;是正常地应对、了知。两者不矛盾——不执着不等于不知道，知道不等于要执着。了空居士概括为：<strong>不被现象所迷惑，保持最清净的心去看待一切。</strong></p><h3 id="_2-心如明镜" tabindex="-1">2. 心如明镜 <a class="header-anchor" href="#_2-心如明镜" aria-label="Permalink to &quot;2. 心如明镜&quot;">​</a></h3><p><strong>原文</strong>：心如明镜，照物而不染。</p><p><strong>解读</strong>：镜子照见万物，但它们不会被镜子&quot;吸收&quot;。心也应如此——看到、知道、应对，但不被所看到的东西污染。</p><h3 id="_3-离相" tabindex="-1">3. 离相 <a class="header-anchor" href="#_3-离相" aria-label="Permalink to &quot;3. 离相&quot;">​</a></h3><p><strong>原文</strong>：凡所有相，皆是虚妄。若见诸相非相，即见如来。</p><p><strong>解读</strong>：不被表面现象迷惑，看穿现象背后的实质。但不是否定现象，而是不被现象&quot;绑住&quot;。</p><h3 id="_4-无私心分别" tabindex="-1">4. 无私心分别 <a class="header-anchor" href="#_4-无私心分别" aria-label="Permalink to &quot;4. 无私心分别&quot;">​</a></h3><p><strong>原文</strong>：无分别是无私心分别，不是不辨是非。</p><p><strong>解读</strong>：很多人误解&quot;无分别心&quot;是什么都不分。了空居士纠正：走路该从门出去还是从墙壁出去？这需要分别。真正的无分别，是没有私心在作祟，客观如实地判断。</p><h3 id="_5-定慧等持" tabindex="-1">5. 定慧等持 <a class="header-anchor" href="#_5-定慧等持" aria-label="Permalink to &quot;5. 定慧等持&quot;">​</a></h3><p><strong>原文</strong>：一心念佛本来就具足定慧。一心是定，念念分明是慧。</p><p><strong>解读</strong>：定和慧不是两件事。心静下来（定）的同时，了了分明（慧）也在。不要追求先定后慧，它们是同时的。</p><h3 id="_6-三昧即非有心非无心" tabindex="-1">6. 三昧即非有心非无心 <a class="header-anchor" href="#_6-三昧即非有心非无心" aria-label="Permalink to &quot;6. 三昧即非有心非无心&quot;">​</a></h3><p><strong>原文</strong>：正入定时就不见有无之心，不是有心入也不是无心入。</p><p><strong>解读</strong>：真正的定境，不是强行让自己&quot;入定&quot;，也不是放任自己散漫。是自然而然地进入一种身心宁静的状态。</p><h3 id="_7-四相即非菩萨" tabindex="-1">7. 四相即非菩萨 <a class="header-anchor" href="#_7-四相即非菩萨" aria-label="Permalink to &quot;7. 四相即非菩萨&quot;">​</a></h3><p><strong>原文</strong>：若菩萨有我相、人相、众生相、寿者相，即非菩萨。</p><p><strong>解读</strong>：只要执着于自我、他人、众生、时间这些概念，就不是真菩萨。度了无量众生，心中却觉得&quot;实无众生得灭度者&quot;，这才是菩萨的心态。</p><h3 id="_8-离相即客观" tabindex="-1">8. 离相即客观 <a class="header-anchor" href="#_8-离相即客观" aria-label="Permalink to &quot;8. 离相即客观&quot;">​</a></h3><p><strong>原文</strong>：离相，就是以最清净最客观的心去看待一切，包括看待自己。</p><p><strong>解读</strong>：离相不是逃避，而是像旁观者一样看待发生在自己身上的事。司马光砸缸——救人要紧，不管金鱼缸会不会被骂，这就是离相。</p><h3 id="_9-知见无见" tabindex="-1">9. 知见无见 <a class="header-anchor" href="#_9-知见无见" aria-label="Permalink to &quot;9. 知见无见&quot;">​</a></h3><p><strong>原文</strong>：知见无见，斯即涅槃，无漏真净。</p><p><strong>解读</strong>：不要带着任何成见去看问题和看自己。六祖对惠明说&quot;不思善不思恶，正与么时，那个是明上座的本来面目&quot;——没有成见的时候，佛性自然显现。</p><h3 id="_10-凡所有相皆是虚妄" tabindex="-1">10. 凡所有相皆是虚妄 <a class="header-anchor" href="#_10-凡所有相皆是虚妄" aria-label="Permalink to &quot;10. 凡所有相皆是虚妄&quot;">​</a></h3><p><strong>原文</strong>：凡所有相，皆是虚妄。若见诸相非相，即见如来。</p><p><strong>解读</strong>：&quot;虚妄&quot;不是没有，而是不永恒、会变化。这是个好消息——正因为会变化，我们才能通过努力让它变好。所以&quot;虚妄&quot;不是消极，是最积极的。</p><h3 id="_11-一相无相" tabindex="-1">11. 一相无相 <a class="header-anchor" href="#_11-一相无相" aria-label="Permalink to &quot;11. 一相无相&quot;">​</a></h3><p><strong>原文</strong>：一相无相——任何一个现象都没有一个永恒不变的自我。</p><p><strong>解读</strong>：山不是永恒的山，海不是永恒的海，一切都在变化中。放下&quot;必须永恒&quot;的执念，心就轻松了。</p><h3 id="_12-离欲即不贪著" tabindex="-1">12. 离欲即不贪著 <a class="header-anchor" href="#_12-离欲即不贪著" aria-label="Permalink to &quot;12. 离欲即不贪著&quot;">​</a></h3><p><strong>原文</strong>：离欲就是不贪著，不是断绝。</p><p><strong>解读</strong>：吃饭穿衣是正常的，不挑剔、不贪恋就好。古代有人将&quot;离欲&quot;解为&quot;断绝一切欲望&quot;，这是错的。佛祖也托钵吃饭，示现正常生活。</p><h3 id="_13-无所住行布施" tabindex="-1">13. 无所住行布施 <a class="header-anchor" href="#_13-无所住行布施" aria-label="Permalink to &quot;13. 无所住行布施&quot;">​</a></h3><p><strong>原文</strong>：菩萨于法，应无所住行于布施。</p><p><strong>解读</strong>：做任何事情都不带私心目的，大公无私坦坦荡荡。看到路上有石头碍事，很自然地搬开——不为了给人看，不为了求表扬。</p><h3 id="_14-助人如己" tabindex="-1">14. 助人如己 <a class="header-anchor" href="#_14-助人如己" aria-label="Permalink to &quot;14. 助人如己&quot;">​</a></h3><p><strong>原文</strong>：帮助别人就像帮助自己的手足一样自然。</p><p><strong>解读</strong>：手不会觉得&quot;我今天帮脚走了很多路，很累&quot;，手脚是一体的。真正有慈悲心的人帮助别人就像帮助自己，没有&quot;我在帮你&quot;的念头。</p><h3 id="_15-三心不可得" tabindex="-1">15. 三心不可得 <a class="header-anchor" href="#_15-三心不可得" aria-label="Permalink to &quot;15. 三心不可得&quot;">​</a></h3><p><strong>原文</strong>：过去心不可得，现在心不可得，未来心不可得。</p><p><strong>解读</strong>：心念刹那刹那在变化，没有一个固定的&quot;心&quot;可以抓住。过去已去，未来未至，现在无住。这不是消极，而是告诉你——不要被任何一时的念头困住。</p><h3 id="_16-无实无虚" tabindex="-1">16. 无实无虚 <a class="header-anchor" href="#_16-无实无虚" aria-label="Permalink to &quot;16. 无实无虚&quot;">​</a></h3><p><strong>原文</strong>：如来所得阿耨多罗三藐三菩提，于是中无实无虚。</p><p><strong>解读</strong>：清净心的境界，既没有一个具体的东西可以执着（无实），也不是一片空白（无虚）。高兴知道高兴，但不执着高兴；悲伤知道悲伤，但不执着悲伤。一切了了分明，但心不动摇。</p><h3 id="_17-究竟无我" tabindex="-1">17. 究竟无我 <a class="header-anchor" href="#_17-究竟无我" aria-label="Permalink to &quot;17. 究竟无我&quot;">​</a></h3><p><strong>原文</strong>：一切法无我、无人、无众生、无寿者。</p><p><strong>解读</strong>：一切现象都没有一个永恒不变的自我。不执着于&quot;我在修行&quot;&quot;我在度众生&quot;&quot;我达到了什么境界&quot;——这些念头一起，就已经偏离了清净心。</p><h3 id="_18-能净业障" tabindex="-1">18. 能净业障 <a class="header-anchor" href="#_18-能净业障" aria-label="Permalink to &quot;18. 能净业障&quot;">​</a></h3><p><strong>原文</strong>：以今世人轻贱故，先世罪业即为消灭。</p><p><strong>解读</strong>：受持《金刚经》的人被人轻贱，不生嗔恚——这就是历境炼心，业障在清净心中自然消融。业障不是定业，是可以化解的。</p><h3 id="_19-一体同观" tabindex="-1">19. 一体同观 <a class="header-anchor" href="#_19-一体同观" aria-label="Permalink to &quot;19. 一体同观&quot;">​</a></h3><p><strong>原文</strong>：一体同观，将别人和自己看成一个整体。</p><p><strong>解读</strong>：一视同仁是&quot;对待一样&quot;，一体同观是&quot;本是一体&quot;。看到别人受苦就像自己受苦，看到别人快乐就像自己快乐——不是修养出来的，是证得的境界。</p><h3 id="_20-了即业障本空" tabindex="-1">20. 了即业障本空 <a class="header-anchor" href="#_20-了即业障本空" aria-label="Permalink to &quot;20. 了即业障本空&quot;">​</a></h3><p><strong>原文</strong>：了即业障本来空，未了还需还宿债。</p><p><strong>解读</strong>：真正彻悟的人，业障对他来说已无实质影响。如同大海能容纳一切污浊而不被污染——不是现象消失，而是本质不受影响。但未悟的人，还是要老实面对因果。</p><h3 id="_21-是法平等无有高下" tabindex="-1">21. 是法平等无有高下 <a class="header-anchor" href="#_21-是法平等无有高下" aria-label="Permalink to &quot;21. 是法平等无有高下&quot;">​</a></h3><p><strong>原文</strong>：是法平等，无有高下，是名阿耨多罗三藐三菩提。</p><p><strong>解读</strong>：清净心面对一切现象没有厚此薄彼。但这不是说朱古力和牛粪无区别——平等是指心态上不分别，做事时还是要分清。吃饭不能塞进眼睛里，这是智慧，不是不分别。</p><h3 id="_22-无我不等于没有" tabindex="-1">22. 无我不等于没有 <a class="header-anchor" href="#_22-无我不等于没有" aria-label="Permalink to &quot;22. 无我不等于没有&quot;">​</a></h3><p><strong>原文</strong>：无我是无私心妄想，不是人消失。</p><p><strong>解读</strong>：很多人以为&quot;无我&quot;就是人没有了，堕入空的邪见。无我是无私心妄想，一切都是般若智慧的流露——该吃饭吃饭，该做事做事，只是没有贪嗔痴慢疑。</p><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><p><strong>在日常生活中</strong>：</p><ul><li>遇到让你生气的事，试着做&quot;镜子&quot;——知道自己在生气，但不被气带走</li><li>遇到让你欢喜的事，知道自己在欢喜，但不沉溺其中</li><li>对事不对人，客观判断</li><li>被人骂时，试着用旁观者的心态——&quot;他为什么这么激动？&quot;而不是&quot;他在骂我！&quot;</li><li>不平静的时候问问自己：&quot;我为什么要不平静，这样是正确的吗？&quot;</li><li>做任何事不带私心目的，像司马光砸缸一样——救人最重要，其他的不管</li></ul><p><strong>在静坐中</strong>：</p><ul><li>杂念来了，看着它，不跟随，不抵制——这就是对境不住</li><li>不是要&quot;消除&quot;念头，而是不被念头牵着跑</li></ul><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 对境不住是&quot;不住&quot;，对法不执是&quot;不执&quot;</li><li><a href="/10-核心模型/model-天人合一">天人合一</a> — 对境不住是天人合一的心态基础</li><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 对境不住在日常生活中的应用</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第1分（法会由分）</li><li>金刚经第2分（善现启请分）</li><li>金刚经第3分（大乘正宗分）</li><li>金刚经第4分（妙行无住分）</li><li>金刚经第5分（如理实见分）</li><li>金刚经第6分（正信希有分）</li><li>金刚经第7分（无得无说分）</li><li>金刚经第8分（依法出生分）</li><li>金刚经第9分（一相无相分）</li><li>金刚经第10分（庄严净土分）</li><li>金刚经第11分（无为福胜分）</li><li>金刚经第12分（尊重正教分）</li><li>金刚经第15分（持经功德分）</li><li>金刚经第16分（能净业障分）</li><li>金刚经第17分（究竟无我分）</li><li>金刚经第18分（一体同观分）</li><li>金刚经第19分（法界通化分）</li><li>金刚经第20分（离色离相分）</li><li>金刚经第23分（净心行善分）</li><li>金刚经第25分（化无所化分）</li><li>金刚经第26分（法身非相分）</li><li>金刚经第32分（应化非真分）</li><li>答疑专辑2014/2019</li><li>六祖法宝坛经</li><li>心经讲解</li><li>道德经讲解</li></ul><blockquote><p>来源：<a href="/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a>、<a href="/10了空居士讲《金刚经》-第十分庄严净土分20161104">10了空居士讲《金刚经》-第十分庄严净土分20161104</a> 蒸馏日期：2026-05-05（第一版）2026-05-05（第二版）2026-05-06（第三版，共22原子）</p></blockquote>',85)])])}const g=t(e,[["render",n]]);export{d as __pageData,g as default};
